const CACHE = "visual-mark-" + VERSION;
const FONTS = "visual-mark-fonts";
const PRECACHE = ["index.html", "manifest.webmanifest", "apple-touch-icon.png", "icon-192.png", "icon-512.png", "icon-maskable-512.png", "favicon-32.png", "img/cover.jpg", "img/mark01-hero.jpg", "img/mark01-v09.jpg", "img/mark01-v14.jpg", "img/mark01-v35.jpg", "img/mark02-hero.jpg", "img/mark02-v01.jpg", "img/mark02-v13.jpg", "img/mark02-v18.jpg", "img/mark03-hero.jpg", "img/mark03-v01.jpg", "img/mark03-v13.jpg", "img/mark03-v31.jpg", "img/mark04-hero.jpg", "img/mark04-v10.jpg", "img/mark04-v21.jpg", "img/mark04-v35.jpg", "img/mark05-hero.jpg", "img/mark05-v01.jpg", "img/mark05-v25.jpg", "img/mark05-v35.jpg", "img/mark06-hero.jpg", "img/mark06-v07.jpg", "img/mark06-v30.jpg", "img/mark06-v45.jpg", "img/mark07-hero.jpg", "img/mark07-v14.jpg", "img/mark07-v24.jpg", "img/mark07-v31.jpg", "img/mark08-hero.jpg", "img/mark08-v14.jpg", "img/mark08-v22.jpg", "img/mark08-v31.jpg", "img/mark09-hero.jpg", "img/mark09-v14.jpg", "img/mark09-v33.jpg", "img/mark09-v42.jpg", "img/mark10-hero.jpg", "img/mark10-v13.jpg", "img/mark10-v17.jpg", "img/mark10-v46.jpg", "img/mark11-hero.jpg", "img/mark11-v01.jpg", "img/mark11-v12.jpg", "img/mark11-v20.jpg", "img/mark12-hero.jpg", "img/mark12-v13.jpg", "img/mark12-v28.jpg", "img/mark12-v41.jpg", "img/mark13-hero.jpg", "img/mark13-v14.jpg", "img/mark13-v24.jpg", "img/mark13-v32.jpg", "img/mark14-hero.jpg", "img/mark14-v22.jpg", "img/mark14-v32.jpg", "img/mark14-v66.jpg", "img/mark15-hero.jpg", "img/mark15-v21.jpg", "img/mark15-v33.jpg", "img/mark15-v42.jpg", "img/mark16-hero.jpg", "img/mark16-v09.jpg", "img/mark16-v14.jpg", "img/mark16-v19.jpg", "img/welcome-1.jpg", "img/welcome-2.jpg", "img/welcome-3.jpg"];

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(PRECACHE)));
});

self.addEventListener("message", (event) => {
  if (event.data === "skipWaiting") self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith("visual-mark-") && k !== CACHE && k !== FONTS).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);

  // Google Fonts: serve from cache, refresh in the background
  if (url.hostname === "fonts.googleapis.com" || url.hostname === "fonts.gstatic.com") {
    event.respondWith(caches.open(FONTS).then(async (c) => {
      const hit = await c.match(req);
      const net = fetch(req).then((res) => { if (res && (res.ok || res.type === "opaque")) c.put(req, res.clone()); return res; }).catch(() => hit);
      return hit || net;
    }));
    return;
  }
  if (url.origin !== self.location.origin) return;

  // App pages: always answer with the stored index.html (the app routes on #hash)
  if (req.mode === "navigate") {
    event.respondWith(caches.match("index.html", { ignoreSearch: true }).then((hit) => hit || fetch(req)));
    return;
  }

  // Everything else from this site: cache first, then network
  event.respondWith(caches.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req).then((res) => {
    if (res && res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(req, copy)); }
    return res;
  })));
});
